/**
 * Resolve parent folder from --parent-folder-path, --parent-folder-key, or
 * --personal-workspace options.
 *
 * Returns the fully qualified folder path string the deploy endpoint expects
 * as `folderFullyQualifiedName`, or undefined if none of the three options
 * was provided.
 *
 * Mutual exclusivity is enforced at parse time by Commander via
 * `Option#conflicts()` in the calling command — see `deploy-run.ts`.
 * Personal Workspace is resolved via Orchestrator's `GetPersonalWorkspace`
 * endpoint using the current auth context — see
 * {@link resolvePersonalWorkspace} for the contract.
 */
export declare function resolveParentFolder(options: {
    folderPath?: string;
    folderKey?: string;
    personalWorkspace?: boolean;
    tenant?: string;
    loginValidity?: number;
    /** Pin folder-lookup auth to this exact `.uipath/.auth` path, forwarded to
     *  `resolvePersonalWorkspace`/`resolveFolder` so it matches the deploy auth. */
    envFilePath?: string;
}): Promise<string | undefined>;
/**
 * Resolve a folder to its full identity — key plus canonical FQN — from
 * --parent-folder-path or --parent-folder-key.
 *
 * Unlike {@link resolveParentFolder}, which passes a --parent-folder-path
 * through verbatim (the tenant Pipelines install takes an FQN and validates
 * server-side), this always hits the Folders API: feed deploys need the
 * location folder's *key* for the auto-install request's
 * `installationFolderKey` — the server creates the solution folder under that
 * key, so sending the wrong one silently installs in the wrong place.
 *
 * Returns `undefined` when neither option was provided.
 */
export declare function resolveFolderInfo(options: {
    folderPath?: string;
    folderKey?: string;
    tenant?: string;
    loginValidity?: number;
    envFilePath?: string;
}): Promise<{
    key: string;
    path: string;
} | undefined>;
